import { debugLogger, coreEvents } from '@google/gemini-cli-core';
import type { SlashCommand } from '../ui/commands/types.js';
import type { ICommandLoader } from './types.js';

export interface CommandConflict {
  name: string;
  winner: SlashCommand;
  losers: Array<{
    command: SlashCommand;
    renamedTo: string;
  }>;
